    nrm.set(g2.attributes.normal.array, vo * 3);
    uv3.set(g2.attributes.uv.array, vo * 2);
    const gi = g2.index.array;
    for (let k2 = 0; k2 < gi.length; k2++) idx[io + k2] = gi[k2] + vo;
